import {PaginationContainer} from './styles';
import {IoIosArrowDroprightCircle,IoIosArrowDropleftCircle} from 'react-icons/io';
import { PropertyPage } from '../../types/property';

type Props ={
    page: PropertyPage;
    onChange: Function;
}

const Pagination = ({page, onChange} : Props) => {
    return(
        <PaginationContainer>
           <div className='pagination-box'>
                <button className='pagination-button' disabled={page.first} onClick={()=> onChange(page.number-1 )} >
                <IoIosArrowDropleftCircle size={10} className='left'/>
                </button>
                <p>{`${page.number+1} de ${page.totalPages}`}</p>
                <button className='pagination-button' disabled={page.last} onClick={()=> onChange(page.number+1 )} >
                <IoIosArrowDroprightCircle />
                </button>
           </div>
           </PaginationContainer>

    
    )
}

export default Pagination;
